@router.get('/api/vault/{file_id}/key')
def get_vault_file_key(
    file_id: str,
    user: User = Depends(get_current_user)
):
    vault_item = SecureVaultItem.get_or_none(
        (SecureVaultItem.file_id == file_id) & (SecureVaultItem.owner_id == user.id)
    )
    if not vault_item:
        raise HTTPException(status_code=404, detail="Vault item not found")

    return {
        "file_id": vault_item.file_id,
        "wrapped_encryption_key": vault_item.encryption_key,
        "cipher_suite": vault_item.cipher_suite
    }
